// Shared corpus for the terminal and review-like names of a stored workflow.
//
// The backend (services/workflow-status-filter.ts safeStates, which reads a
// stored definition through sanitizeStoredDefinition and falls back to the
// built-in names of a kind when it cannot) is authoritative.
// frontend/src/lib/workflow-vocabulary.ts is a port that feeds the /tasks
// presets and the Home widgets. `expected` was generated by the backend, not
// written by hand: for each definition below, the sorted names that
// buildTaskStatusFilter (kinds "review" and "terminal", one default workflow
// row) selects, read with `npx tsx` from backend/ over this file. The backend
// test below computes the same thing, so a failing run of it prints the
// backend's current answers. Consumed by:
//  - backend/tests/unit/workflow-vocabulary-parity.test.ts: runs the backend
//    over every definition and asserts `expected`, so a backend change breaks
//    the backend test;
//  - frontend/tests/unit/WorkflowVocabulary.test.ts: runs the port over the
//    same file and asserts the same `expected`.
// Plain data, no dependency on either package, like confidence-fixtures.ts.

export interface WorkflowVocabularyFixture {
  name: string;
  /** The stored definition as the API lists it (possibly not a valid one). */
  definition: unknown;
  expected: { review: string[]; terminal: string[] };
}

type StateSpec = [name: string, terminal: boolean];
type EdgeSpec = [from: string, to: string];

function def(initialState: string, states: StateSpec[], edges: EdgeSpec[]) {
  return {
    initialState,
    states: states.map(([name, terminal]) => ({ name, label: name, terminal })),
    transitions: edges.map(([from, to]) => ({ from, to })),
  };
}

const SEVEN_STAGE_STATES: StateSpec[] = [
  ["spec", false],
  ["plan", false],
  ["implement", false],
  ["test", false],
  ["review", false],
  ["done", true],
];

export const WORKFLOW_VOCABULARY_FIXTURES: WorkflowVocabularyFixture[] = [
  {
    name: "built-in workflow",
    definition: def(
      "open",
      [["open", false], ["in_progress", false], ["review", false], ["done", true]],
      [["open", "in_progress"], ["in_progress", "review"], ["in_progress", "done"], ["in_progress", "open"], ["review", "done"], ["review", "in_progress"]],
    ),
    expected: { review: ["review"], terminal: ["done"] },
  },
  {
    name: "seven-stage pipeline with open as the entry state",
    definition: def(
      "open",
      [["open", false], ...SEVEN_STAGE_STATES],
      [["open", "spec"], ["spec", "plan"], ["plan", "implement"], ["implement", "test"], ["test", "review"], ["test", "implement"], ["review", "done"], ["review", "implement"], ["implement", "plan"], ["plan", "spec"], ["spec", "open"]],
    ),
    expected: { review: ["review"], terminal: ["done"] },
  },
  {
    name: "QA flow with custom review-like and two terminal names",
    definition: def(
      "open",
      [["open", false], ["work", false], ["qa", false], ["shipped", true], ["wontfix", true]],
      [["open", "work"], ["work", "qa"], ["qa", "shipped"], ["qa", "work"], ["work", "wontfix"]],
    ),
    expected: { review: ["qa"], terminal: ["shipped", "wontfix"] },
  },
  {
    name: "entry-edge: targets of the entry state and dead ends are not review-like",
    definition: def(
      "open",
      [["open", false], ["hotfix", false], ["work", false], ["check", false], ["done", true], ["closed", true], ["lonely", false]],
      [["open", "done"], ["done", "closed"], ["closed", "done"], ["open", "hotfix"], ["hotfix", "done"], ["open", "work"], ["work", "check"], ["check", "done"], ["check", "work"], ["open", "lonely"]],
    ),
    expected: { review: ["check"], terminal: ["closed", "done"] },
  },
  {
    name: "initial backlog with a backlog -> review edge",
    definition: def(
      "backlog",
      [["backlog", false], ["review", false], ["done", true]],
      [["backlog", "review"], ["review", "done"]],
    ),
    expected: { review: ["review"], terminal: ["done"] },
  },
  {
    name: "legacy copy of the built-in default (initial backlog, backlog -> open)",
    definition: def(
      "backlog",
      [["backlog", false], ["open", false], ["in_progress", false], ["review", false], ["done", true]],
      [["backlog", "open"], ["open", "in_progress"], ["in_progress", "review"], ["in_progress", "done"], ["review", "done"]],
    ),
    expected: { review: ["review"], terminal: ["done"] },
  },
  {
    name: "states list without a transitions list",
    definition: {
      initialState: "open",
      states: [
        { name: "open", label: "Open", terminal: false },
        { name: "check", label: "Check", terminal: false },
        { name: "shipped", label: "Shipped", terminal: true },
      ],
    },
    expected: { review: ["review"], terminal: ["shipped"] },
  },
  {
    name: "two terminal states with a review state reachable from two places",
    definition: def(
      "open",
      [["open", false], ["build", false], ["verify", false], ["accept", false], ["done", true], ["rejected", true]],
      [["open", "build"], ["build", "verify"], ["build", "accept"], ["verify", "accept"], ["accept", "done"], ["accept", "rejected"], ["verify", "build"]],
    ),
    expected: { review: ["accept"], terminal: ["done", "rejected"] },
  },
  {
    name: "legacy seven-stage pipeline (initial backlog, edges into backlog)",
    definition: def(
      "backlog",
      [["backlog", false], ...SEVEN_STAGE_STATES],
      [["backlog", "spec"], ["spec", "plan"], ["spec", "backlog"], ["plan", "implement"], ["implement", "test"], ["test", "review"], ["review", "done"], ["review", "implement"]],
    ),
    expected: { review: ["review"], terminal: ["done"] },
  },
  {
    name: "initial backlog with edges out of backlog to a terminal state, to the entry state and twice to one target",
    definition: def(
      "backlog",
      [["backlog", false], ["open", false], ["spec", false], ["review", false], ["done", true]],
      [["backlog", "done"], ["backlog", "open"], ["backlog", "spec"], ["backlog", "spec"], ["spec", "review"], ["review", "done"]],
    ),
    expected: { review: ["review"], terminal: ["done"] },
  },
  {
    name: "backlog state kept in a definition whose entry state is open",
    definition: def(
      "open",
      [["open", false], ["backlog", false], ["work", false], ["check", false], ["done", true]],
      [["open", "work"], ["work", "backlog"], ["backlog", "check"], ["work", "check"], ["check", "done"]],
    ),
    expected: { review: ["check"], terminal: ["done"] },
  },
  {
    name: "terminal backlog state",
    definition: def(
      "open",
      [["open", false], ["work", false], ["backlog", true], ["done", true]],
      [["open", "work"], ["work", "done"], ["work", "backlog"]],
    ),
    expected: { review: [], terminal: ["done"] },
  },
  {
    name: "abandoned stored as an ordinary state that ends in a terminal one",
    definition: def(
      "open",
      [["open", false], ["backlog", false], ["abandoned", false], ["done", true]],
      [["open", "backlog"], ["backlog", "done"], ["abandoned", "done"]],
    ),
    expected: { review: ["abandoned"], terminal: ["done"] },
  },
  {
    name: "a name listed twice, terminal in the first entry only",
    definition: {
      initialState: "open",
      states: [
        { name: "open", label: "Open", terminal: false },
        { name: "check", label: "Check", terminal: false },
        { name: "done", label: "Done", terminal: true },
        { name: "done", label: "Done again", terminal: false },
      ],
      transitions: [
        { from: "open", to: "check" },
        { from: "check", to: "done" },
      ],
    },
    expected: { review: [], terminal: ["done"] },
  },
  {
    name: "states is not a list",
    definition: { initialState: "open", states: "open,done", transitions: [] },
    expected: { review: ["review"], terminal: ["done"] },
  },
  {
    name: "transitions is not a list",
    definition: {
      initialState: "open",
      states: [
        { name: "open", label: "Open", terminal: false },
        { name: "check", label: "Check", terminal: false },
        { name: "shipped", label: "Shipped", terminal: true },
      ],
      transitions: "open>check",
    },
    expected: { review: ["review"], terminal: ["shipped"] },
  },
  {
    name: "definition is null",
    definition: null,
    expected: { review: ["review"], terminal: ["done"] },
  },
  {
    name: "a state entry that is not an object",
    definition: {
      initialState: "open",
      states: [{ name: "open", label: "Open", terminal: false }, null, { name: "done", label: "Done", terminal: true }],
      transitions: [],
    },
    expected: { review: ["review"], terminal: ["done"] },
  },
];
